const raw = $input.first().json.text ?? $input.first().json.output ?? $input.first().json.response ?? '';
const cleaned = String(raw).replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); } catch { parsed = { reply: cleaned || 'Tell me a little more about what you are building.', segment: null, capture: { name: null, email: null } }; }
const request = $('Sage Chat Webhook').first().json.body ?? $('Sage Chat Webhook').first().json;
const allowed = ['agtech', 'inspection', 'freight', 'mobile', 'custom'];
const requestedSegment = allowed.includes(request.segment) ? request.segment : null;
return [{ json: {
  reply: String(parsed.reply ?? 'Tell me a little more about what you are building.'),
  segment: requestedSegment ?? (allowed.includes(parsed.segment) ? parsed.segment : null),
  capture: {
    name: request.contact?.name ?? parsed.capture?.name ?? null,
    email: request.contact?.email ?? parsed.capture?.email ?? null
  },
  event: request.event ?? 'chat',
  sendRecap: request.sendRecap === true,
  consent: request.consent ?? {},
  messages: Array.isArray(request.messages) ? request.messages : []
} }];
